	cin >> T;

	for (int t = 0; t < T; t++) {
		long long A, B;
		cin >> A >> B;

		char ans = '$';

		if (A > 0) {
			ans = '+';
		}
		else if (A <= 0 && B >= 0) {
			ans = '0';
		}
		else {
			if ((B - A + 1) % 2 == 0) {
				ans = '+';
			}
			if ((B - A + 1) % 2 == 1) {
				ans = '-';
			}
		}

